	const cacheOrderRef = useRef<string[]>([])
	const cacheMax = 20

	const previewTheme = useMemo(() => variantTheme(variant), [variant])
	const columns = useMemo(() => columnsFor(variant), [variant])
	const dataset = datasets[index - 1]
